// Script to create a proper default/index.js for Prisma client
const fs = require('fs');
const path = require('path');

const defaultDir = path.join(__dirname, '../node_modules/.prisma/client/default');
const clientPath = path.join(__dirname, '../node_modules/.prisma/client/client.ts');

// Ensure directory exists
if (!fs.existsSync(defaultDir)) {
  fs.mkdirSync(defaultDir, { recursive: true });
}

// Create index.js that webpack can process
const indexContent = `// Auto-generated by create-prisma-default.js
// This file allows @prisma/client to find the generated Prisma client
'use strict';

// Export a module that webpack can resolve
// The actual client.ts will be processed by webpack's TypeScript loader
module.exports = {
  // PrismaClient will be resolved by webpack at build time
  get PrismaClient() {
    // Use __webpack_require__ if available (webpack context)
    if (typeof __webpack_require__ !== 'undefined') {
      return __webpack_require__('../client').PrismaClient;
    }
    // Fallback for Node.js (shouldn't happen in webpack context)
    try {
      return require('../client').PrismaClient;
    } catch (e) {
      throw new Error('PrismaClient not found. Run: npx prisma generate');
    }
  }
};
`;

fs.writeFileSync(path.join(defaultDir, 'index.js'), indexContent);
console.log('✅ Created Prisma default/index.js');
